-- ============================================================
-- 09. 인코아(INCORE) + 미라렛(MIRALET) 3종 등록
--     실행: Supabase 대시보드 → SQL Editor에 붙여넣고 Run (재실행 안전)
--
--     이미지는 저장소에 함께 커밋된 assets/img/products/miralet/* 를 씁니다.
--     ⚠️ 가격·MOQ·납기는 아직 제조사 미제공 → '문의'로 넣습니다. 받는 대로 교체하세요.
-- ============================================================

-- ---------- 제조사 ----------
insert into companies (id, brand, cat, name, tagline, intro, location, since, staff, export,
                       brn, ceo, tel, site, certs, moq_policy, logo, cover)
values ('incore', 'MIRALET', 'beauty',
  $json${"vi":"INCORE (MIRALET)","ko":"주식회사 인코아","en":"INCORE Co., Ltd. (MIRALET)"}$json$::jsonb, $json${"vi":"Nhà sản xuất thiết bị y tế làm mỹ phẩm — thương hiệu MIRALET","ko":"의료기기 제조사가 만드는 화장품 — 더마코스메틱 브랜드 미라렛","en":"A medical device maker turned dermacosmetic brand — MIRALET"}$json$::jsonb, $json${"vi":"INCORE (thành lập 2014, Daegu) nghiên cứu và sản xuất thiết bị y tế từ chitosan — nổi bật là băng cầm máu HEMOBLOCK và băng vết thương hydrogel HYLACELL được bác sĩ da liễu kê đơn. MIRALET là dòng dermacosmetic ra đời từ chính công thức đó: sản phẩm chăm sóc da chứa PDRN thực vật và exosome thực vật, dùng hằng ngày.","ko":"(주)인코아는 2014년 설립된 대구 소재 의료기기 연구·제조기업으로, 키토산 지혈재 헤모블럭(HEMOBLOCK)과 피부과에서 처방되는 하이드로겔 창상피복재 하이라셀(HYLACELL)을 만듭니다. 미라렛(MIRALET)은 그 포뮬러를 바탕으로 만든 더마코스메틱 라인으로, 식물성 PDRN과 식물 엑소좀을 담아 매일 쓰는 스킨케어로 풀어냈습니다.","en":"INCORE (founded 2014, Daegu) develops and manufactures chitosan-based medical devices — notably the HEMOBLOCK hemostatic dressing and HYLACELL, a hydrogel wound dressing prescribed by dermatologists. MIRALET is its dermacosmetic line built on the same formulation work, delivering plant-based PDRN and plant exosomes in daily-use skincare."}$json$::jsonb, $json${"vi":"Daegu, Hàn Quốc","ko":"대구 동구","en":"Daegu, Korea"}$json$::jsonb,
  '2014', '—', '—',
  '503-86-14502', '김동탁', '010-6219-3514', 'incoremedi.com',
  array['의료기기 제조','FDA Class III (Hemoblock S)','기능성화장품(미백)']::text[], '문의', 'assets/img/products/miralet/ampoule.jpg', 'assets/img/products/miralet/skinbooster.jpg')
on conflict (id) do update set
  brand=excluded.brand, cat=excluded.cat, name=excluded.name, tagline=excluded.tagline,
  intro=excluded.intro, location=excluded.location, since=excluded.since,
  brn=excluded.brn, ceo=excluded.ceo, tel=excluded.tel, site=excluded.site,
  certs=excluded.certs, moq_policy=excluded.moq_policy, logo=excluded.logo, cover=excluded.cover;

-- ---------- 미라렛 피토 인텐시브 앰플 30ml ----------
insert into products (id, company_id, cat, brand, origin, name, tagline, brand_story,
                      img, gallery, video, detail, inquiries, views,
                      featured, is_new, published, created_at, negotiable)
values ('p10', 'incore', 'beauty', 'MIRALET', 'Daegu, Korea',
  $json${"vi":"Tinh chất MIRALET Phyto Intensive Ampoule 30ml","ko":"미라렛 피토 인텐시브 앰플 30ml","en":"MIRALET Phyto Intensive Ampoule 30ml"}$json$::jsonb, $json${"vi":"PDRN thực vật 20.000ppm + 3 loại exosome thực vật — tinh chất dưỡng sáng dùng hằng ngày","ko":"식물성 PDRN 20,000ppm + 식물 엑소좀 3종 — 매일 쓰는 미백 기능성 앰플","en":"Plant-based PDRN 20,000ppm with three plant exosomes — a daily brightening ampoule"}$json$::jsonb, $json${"vi":"MIRALET là dòng dermacosmetic của INCORE — nhà sản xuất thiết bị y tế tại Daegu, Hàn Quốc, đứng sau băng cầm máu chitosan HEMOBLOCK và băng vết thương hydrogel HYLACELL được bác sĩ da liễu kê đơn.","ko":"미라렛은 키토산 지혈재 헤모블럭과 피부과 처방 하이드로겔 창상피복재 하이라셀을 만드는 대구 의료기기 제조사 (주)인코아의 더마코스메틱 브랜드입니다.","en":"MIRALET is the dermacosmetic brand of INCORE, the Daegu medical-device maker behind the HEMOBLOCK chitosan hemostatic dressing and HYLACELL, a dermatologist-prescribed hydrogel wound dressing."}$json$::jsonb,
  'assets/img/products/miralet/ampoule.jpg', array['assets/img/products/miralet/ampoule.jpg','assets/img/products/miralet/skinbooster.jpg','assets/img/products/miralet/mist.jpg']::text[], '', $json$[{"type":"p","text":{"vi":"MIRALET Phyto Intensive Ampoule là tinh chất dưỡng da dùng hằng ngày, chứa PDRN thực vật (sodium DNA) ở nồng độ 20.000ppm. Sản phẩm được cấp phép là mỹ phẩm chức năng làm trắng da tại Hàn Quốc, dùng được cho mọi loại da kể cả da nhạy cảm và da khô bên trong.","ko":"미라렛 피토 인텐시브 앰플은 식물성 PDRN(소듐디엔에이)을 20,000ppm 담은 데일리 앰플입니다. 국내 미백 기능성 화장품으로 심사를 받았고, 민감·속건조 피부를 포함한 모든 피부에 사용할 수 있습니다.","en":"MIRALET Phyto Intensive Ampoule is a daily serum carrying plant-based PDRN (sodium DNA) at 20,000ppm. It is registered in Korea as a functional whitening cosmetic and suits all skin types, including sensitive and dehydrated skin."}},{"type":"p","text":{"vi":"Điểm khác biệt: sản phẩm do một công ty thiết bị y tế trực tiếp phát triển. INCORE là nhà sản xuất HYLACELL — băng vết thương hydrogel được bác sĩ da liễu và bác sĩ phẫu thuật thẩm mỹ kê dùng. MIRALET đưa hướng nghiên cứu đó vào sản phẩm chăm sóc da hằng ngày.","ko":"차별점은 의료기기 회사가 직접 만들었다는 점입니다. 인코아는 피부과·성형외과에서 시술에 쓰이는 하이드로겔 창상피복재 하이라셀(HYLACELL)의 제조사이며, 미라렛은 그 연구를 매일 쓰는 스킨케어로 옮긴 라인입니다.","en":"The differentiator is that a medical device company developed it directly. INCORE manufactures HYLACELL, a hydrogel wound dressing used in dermatology and plastic surgery clinics, and MIRALET carries that research into daily skincare."}},{"type":"p","text":{"vi":"Thành phần chính: PDRN thực vật (sodium DNA), 3 loại exosome thực vật (bào tử lá quyển bá, lá diếp cá, hạt lựu), niacinamide, dexpanthenol, phức hợp hyaluronic acid nhiều phân tử lượng, chiết xuất rau má, madecassoside, asiaticoside, allantoin và glutathione.","ko":"주요 성분은 식물성 PDRN(소듐디엔에이), 식물 엑소좀 3종(부처손잎소포·약모밀잎소포·석류씨소포), 나이아신아마이드, 덱스판테놀, 분자량이 다른 복합 히알루론산, 병풀추출물·마데카소사이드·아시아티코사이드, 알란토인, 글루타치온입니다.","en":"Key ingredients: plant-based PDRN (sodium DNA), three plant exosomes (spikemoss leaf, houttuynia leaf and pomegranate seed), niacinamide, dexpanthenol, a multi-weight hyaluronic acid complex, centella extract with madecassoside and asiaticoside, allantoin and glutathione."}},{"type":"p","text":{"vi":"Kết quả thử nghiệm do nhà sản xuất công bố (sử dụng 4 tuần): độ ẩm da tăng từ 62,394 lên 70,033 — cải thiện trên 13%; tông da cải thiện 1,166% (58,000 → 58,667). Số liệu trích từ trang chi tiết sản phẩm của nhà sản xuất.","ko":"제조사가 공개한 4주 사용 시험 결과: 피부 수분 함유량 62.394 → 70.033으로 13% 이상 개선, 피부 톤 58.000 → 58.667로 1.166% 개선. 제조사 상세페이지 기재값입니다.","en":"Manufacturer-published four-week results: skin moisture rose from 62.394 to 70.033, an improvement of over 13%; skin tone improved 1.166% (58.000 → 58.667). Figures as stated on the manufacturer's product page."}},{"type":"p","text":{"vi":"Dòng sản phẩm có hai nồng độ. Ampoule 30ml (PDRN 20.000ppm) dùng cho bước dưỡng cơ bản hằng ngày, mọi loại da. Skinbooster dạng bơm tiêm 2,0ml × 4 (PDRN 100.000ppm) là bản cô đặc dùng cho chăm sóc ban đêm, thiên về da khô và da cần độ đàn hồi.","ko":"라인업은 농도가 두 가지입니다. 앰플 30ml(PDRN 20,000ppm)은 일상 기초 루틴 단계로 모든 피부에, 스킨부스터 2.0ml×4ea(PDRN 100,000ppm)는 고농축 집중 케어로 건성·탄력 피부의 나이트케어에 맞춰져 있습니다.","en":"The line comes in two strengths. The 30ml ampoule (PDRN 20,000ppm) is the everyday base-routine step for all skin types; the 2.0ml × 4ea syringe skinbooster (PDRN 100,000ppm) is the concentrated night-care option aimed at dry skin and elasticity."}},{"type":"p","text":{"vi":"Thông tin sản phẩm: dung tích 30ml · sản xuất tại Hàn Quốc · dùng cho mọi loại da · mỹ phẩm chức năng làm trắng đã qua thẩm định.","ko":"제품 정보: 용량 30ml · 제조국 대한민국 · 모든 피부용 · 미백 기능성 화장품 심사필.","en":"Product information: 30ml · made in Korea · for all skin types · reviewed as a functional whitening cosmetic."}},{"type":"img","seq":true,"src":"assets/img/products/miralet/d01.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d02.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d03.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d04.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d05.jpg","w":848,"h":1552},{"type":"img","seq":true,"src":"assets/img/products/miralet/d06.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d07.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d08.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d09.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d10.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d11.jpg","w":848,"h":1270},{"type":"img","seq":true,"src":"assets/img/products/miralet/d12.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d13.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d14.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d15.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d16.jpg","w":848,"h":2400},{"type":"img","seq":true,"src":"assets/img/products/miralet/d17.jpg","w":848,"h":716}]$json$::jsonb,
  0, 0, true, true, true, '2026-08-04', true)
on conflict (id) do update set
  company_id=excluded.company_id, cat=excluded.cat, brand=excluded.brand, origin=excluded.origin,
