-- ---------- 미라렛 피토 인텐시브 스킨부스터 2.0ml×4ea ----------
insert into products (id, company_id, cat, brand, origin, name, tagline, brand_story,
                      img, gallery, video, detail, inquiries, views,
                      featured, is_new, published, created_at, negotiable)
values ('p11', 'incore', 'beauty', 'MIRALET', 'Daegu, Korea',
  $json${"vi":"MIRALET Phyto Intensive Skinbooster 2,0ml × 4","ko":"미라렛 피토 인텐시브 스킨부스터 2.0ml×4ea","en":"MIRALET Phyto Intensive Skinbooster 2.0ml × 4ea"}$json$::jsonb, $json${"vi":"PDRN thực vật 100.000ppm dạng bơm tiêm — chăm sóc cô đặc ban đêm","ko":"식물성 PDRN 100,000ppm 시린지 타입 — 고농축 나이트케어","en":"Plant-based PDRN at 100,000ppm in a syringe — concentrated night care"}$json$::jsonb, $json${"vi":"MIRALET là dòng dermacosmetic của INCORE — nhà sản xuất thiết bị y tế tại Daegu, Hàn Quốc, đứng sau băng cầm máu chitosan HEMOBLOCK và băng vết thương hydrogel HYLACELL được bác sĩ da liễu kê đơn.","ko":"미라렛은 키토산 지혈재 헤모블럭과 피부과 처방 하이드로겔 창상피복재 하이라셀을 만드는 대구 의료기기 제조사 (주)인코아의 더마코스메틱 브랜드입니다.","en":"MIRALET is the dermacosmetic brand of INCORE, the Daegu medical-device maker behind the HEMOBLOCK chitosan hemostatic dressing and HYLACELL, a dermatologist-prescribed hydrogel wound dressing."}$json$::jsonb,
  'assets/img/products/miralet/skinbooster.jpg', array['assets/img/products/miralet/skinbooster.jpg','assets/img/products/miralet/ampoule.jpg']::text[], '', $json$[{"type":"p","text":{"vi":"Phiên bản cô đặc của dòng Phyto Intensive: PDRN thực vật ở nồng độ 100.000ppm, gấp năm lần bản ampoule. Đóng gói dạng bơm tiêm dùng một lần 2,0ml × 4 ống, lấy đúng liều mỗi lần và hạn chế tiếp xúc không khí.","ko":"피토 인텐시브 라인의 고농축 버전으로, 식물성 PDRN을 앰플의 다섯 배인 100,000ppm 담았습니다. 2.0ml 시린지 4개입이라 매번 정량만 덜어 쓰고 공기 접촉을 줄일 수 있습니다.","en":"The concentrated version of the Phyto Intensive line, carrying plant-based PDRN at 100,000ppm — five times the ampoule. It ships as four 2.0ml single-use syringes, so each application is dosed and air exposure stays low."}},{"type":"p","text":{"vi":"Định vị: chăm sóc cô đặc vào ban đêm, thiên về da khô và da cần độ đàn hồi. Có bổ sung dexpanthenol cùng 3 loại exosome thực vật. Dùng xen kẽ với ampoule dùng hằng ngày là cách nhà sản xuất khuyến nghị.","ko":"포지션은 나이트케어 고농축 집중 케어로, 건성·탄력 피부를 중심에 둡니다. 덱스판테놀과 식물 엑소좀 3종이 함께 들어가며, 데일리 앰플과 번갈아 쓰는 것이 제조사 권장 사용법입니다.","en":"Positioned as concentrated night care aimed at dry skin and elasticity, with dexpanthenol and three plant exosomes added. The manufacturer recommends alternating it with the daily ampoule."}},{"type":"p","text":{"vi":"Thông tin sản phẩm: 2,0ml × 4 ống · sản xuất tại Hàn Quốc · thương hiệu MIRALET của INCORE (Daegu). Trang chi tiết riêng của sản phẩm sẽ được bổ sung.","ko":"제품 정보: 2.0ml × 4개입 · 제조국 대한민국 · (주)인코아(대구) 미라렛 브랜드. 전용 상세페이지는 추후 보강 예정입니다.","en":"Product information: 2.0ml × 4 units · made in Korea · MIRALET brand by INCORE (Daegu). A dedicated detail page will be added later."}}]$json$::jsonb,
