-- ---------- 미라렛 피토 더블 미스트 50g ----------
insert into products (id, company_id, cat, brand, origin, name, tagline, brand_story,
                      img, gallery, video, detail, inquiries, views,
                      featured, is_new, published, created_at, negotiable)
values ('p12', 'incore', 'beauty', 'MIRALET', 'Daegu, Korea',
  $json${"vi":"Xịt khoáng MIRALET Phyto Double Mist 50g","ko":"미라렛 피토 더블 미스트 50g","en":"MIRALET Phyto Double Mist 50g"}$json$::jsonb, $json${"vi":"Xịt khoáng hai lớp chứa PDRN thực vật — cấp ẩm và làm dịu tông da trong ngày","ko":"식물성 PDRN 담은 이중층 미스트 — 낮 동안 수분·톤 정돈","en":"A two-phase mist with plant-based PDRN for hydration and tone through the day"}$json$::jsonb, $json${"vi":"MIRALET là dòng dermacosmetic của INCORE — nhà sản xuất thiết bị y tế tại Daegu, Hàn Quốc, đứng sau băng cầm máu chitosan HEMOBLOCK và băng vết thương hydrogel HYLACELL được bác sĩ da liễu kê đơn.","ko":"미라렛은 키토산 지혈재 헤모블럭과 피부과 처방 하이드로겔 창상피복재 하이라셀을 만드는 대구 의료기기 제조사 (주)인코아의 더마코스메틱 브랜드입니다.","en":"MIRALET is the dermacosmetic brand of INCORE, the Daegu medical-device maker behind the HEMOBLOCK chitosan hemostatic dressing and HYLACELL, a dermatologist-prescribed hydrogel wound dressing."}$json$::jsonb,
  'assets/img/products/miralet/mist.jpg', array['assets/img/products/miralet/mist.jpg','assets/img/products/miralet/ampoule.jpg']::text[], '', $json$[{"type":"p","text":{"vi":"Xịt khoáng dạng hai lớp của dòng MIRALET Phyto, dung tích 50g (1,69oz). Lắc trước khi dùng để hai lớp hòa vào nhau, xịt để cấp ẩm lại trong ngày mà không làm trôi lớp trang điểm.","ko":"미라렛 피토 라인의 이중층 미스트로 용량은 50g(1.69oz)입니다. 흔들어 두 층을 섞은 뒤 뿌리면 메이크업 위에도 낮 동안 수분을 덧입힐 수 있습니다.","en":"A two-phase mist in the MIRALET Phyto line, 50g (1.69oz). Shake to combine the layers, then mist to re-hydrate through the day without disturbing makeup."}},{"type":"p","text":{"vi":"Giữ nguyên hướng thành phần của cả dòng: PDRN thực vật và 3 loại exosome thực vật, hướng đến cấp ẩm và làm đều tông da. Đây là bước bổ sung giữa ngày cho ampoule và skinbooster.","ko":"라인 공통 성분 방향을 그대로 가져갑니다 — 식물성 PDRN과 식물 엑소좀 3종으로 수분과 피부 톤 정돈에 초점을 둡니다. 앰플·스킨부스터를 낮에 보완하는 단계입니다.","en":"It keeps the line's ingredient direction — plant-based PDRN and three plant exosomes focused on hydration and tone — as the midday step that complements the ampoule and skinbooster."}},{"type":"p","text":{"vi":"Thông tin sản phẩm: 50g / 1,69oz · sản xuất tại Hàn Quốc · thương hiệu MIRALET của INCORE (Daegu). Trang chi tiết riêng của sản phẩm sẽ được bổ sung.","ko":"제품 정보: 50g / 1.69oz · 제조국 대한민국 · (주)인코아(대구) 미라렛 브랜드. 전용 상세페이지는 추후 보강 예정입니다.","en":"Product information: 50g / 1.69oz · made in Korea · MIRALET brand by INCORE (Daegu). A dedicated detail page will be added later."}}]$json$::jsonb,
